function F({registerIndicator:R,sourceValues:T,nulls:Z}){R({id:"oa-zltema",name:"Zero-Lag Triple EMA (ZLTEMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"zltema",type:"line",title:"ZLTEMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(i,d){const h=Math.max(1,Math.floor(Number(d.period)||10)),y=T(i,d.source??"close"),n=2/(h+1),k=1-n,M=Math.pow(1/n,1/3),r=n*M,b=r*M,z=Math.max(1,Math.trunc((h-1)/2)),g=new Array(i.length).fill(NaN);let s=-1,w=!0,m=1,c=0,e=0,t=0;for(let a=0;a<i.length;a+=1){const u=y[a];if(!Number.isFinite(u))continue;s<0&&(s=a);const N=y[Math.max(s,a-z)],E=2*u-(Number.isFinite(N)?N:u);c+=n*(E-c);let o,l,f;if(w){m*=k;const A=1-m,p=A!==0?1/A:1;o=p*c,e+=r*(o-e),l=p*e,t+=b*(l-t),f=p*t,w=m>1e-10}else o=c,e+=r*(o-e),l=e,t+=b*(l-t),f=t;const x=3*o-3*l+f;Number.isFinite(x)&&(g[a]=x)}return{zltema:Z(g)}}})}export{F as default};
